head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// getAllFilteredJSON() 의 행 수와 각 행의 col1 값을 한 줄로 출력
scwin.printFiltered = function (strPrefix) {
    var arrJson = $p.getComponentById("target1").getAllFilteredJSON();
    var arrCol1 = [];
    for (var i = 0; i < arrJson.length; i++) {
        arrCol1.push(arrJson[i].col1);
    }
    scwin.setReturnValue(strPrefix + " 조회 행 수 : " + arrJson.length + "  col1 : " + arrCol1.join(", "));
};

// col1 에 'WebSquare' 필터 적용 (2 행만 조회되는 상태를 만든다)
scwin.btn_setFilter_onclick = function (e) {
    $p.getComponentById("target1").setColumnFilter({ type: "row", colIndex: 0, key: "WebSquare", condition: "and", exactMatch: false });
    scwin.printFiltered("[setColumnFilter({colIndex:0, key:'WebSquare'})]");
};

// Number 인덱스로 필터 해제
scwin.btn_removeNumber_onclick = function (e) {
    try {
        $p.getComponentById("target1").removeColumnFilter(0);
        scwin.setReturnValue("[removeColumnFilter(0) - Number] 호출 시 예외 : 없음");
    } catch (objError) {
        scwin.setReturnValue("[removeColumnFilter(0) - Number] 호출 시 예외 : " + objError.message);
    }
    scwin.printFiltered("[removeColumnFilter(0) - Number]");
};

// String 아이디로 필터 해제 (같은 컬럼)
scwin.btn_removeString_onclick = function (e) {
    try {
        $p.getComponentById("target1").removeColumnFilter("col1");
        scwin.setReturnValue("[removeColumnFilter('col1') - String] 호출 시 예외 : 없음");
    } catch (objError) {
        scwin.setReturnValue("[removeColumnFilter('col1') - String] 호출 시 예외 : " + objError.message);
    }
    scwin.printFiltered("[removeColumnFilter('col1') - String]");
};
